import sys,re,random,collections
sys.path.insert(0,"/tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/6d2042d4-5dad-44df-91ef-b85974d663f3/scratchpad")
from common import *
from kub_load import recs
FN="Kubiak Cunn 2009"
SRC="Kubiak, P. J. (2009). Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia, 11(1), 131-165."
LCR="Lane Cove River valley"; NL="Narrabeen Lagoon catchment area"
BOTH=LCR+"; "+NL
EXPR=re.compile(r"(c\.\s*)?(\?)?\s*(\d+(?:\.\d+)?)(?:\s*[–-]\s*(\d+(?:\.\d+)?))?\s*(\+)?\s*(w|y)?(?![a-z])")
def hy(s): return s.replace("–","-").replace("—","-")
def clean(s): return re.sub(r"\s+"," ",hy(s.replace("<u>","").replace("</u>","").replace("**"," "))).strip()
def exprs(raw):
    s=raw.replace("<u>","").replace("</u>","").replace("**"," ")
    s=re.sub(r"\(\s*\d+\s*\)","",s)
    m=re.fullmatch(r"\s*At least (\d+) years?\s*",s)
    if m: return [dict(approx=0,unc=0,lo=m.group(1),hi=None,plus=1,unit="y")]
    m=re.fullmatch(r"\s*Less than (\d+) years?\s*",s)
    if m: return [dict(approx=0,unc=0,lo=m.group(1),hi=None,plus=-1,unit="y")]
    out=[]
    for m in EXPR.finditer(s):
        out.append(dict(approx=bool(m.group(1)),unc=bool(m.group(2)),lo=m.group(3),hi=m.group(4),plus=1 if m.group(5) else 0,unit=m.group(6)))
    return out
def toyears(n):
    v=round(float(n)/52,3); s=f"{v:.3f}".rstrip("0").rstrip("."); return s
def val(e,to_years):
    """returns (value string, converted_from or None)"""
    lo,hi,u=e["lo"],e["hi"],e["unit"]
    if to_years and u=="w":
        a=toyears(lo); b=toyears(hi) if hi else None
        v=f"{a}-{b}" if b else a
        src=f"{lo}-{hi} weeks" if hi else f"{lo} weeks"
    else:
        v=f"{lo}-{hi}" if hi else lo; src=None
    if e["plus"]==1: v=">"+v
    elif e["plus"]==-1: v="<"+v
    return v,src
def sitecode(cell):
    c=cell.strip()
    if not c: return None,None
    m=re.match(r"^(\??p?[RKrk](?:\s*[/;]\s*\??[RKrk])?)(?=$|[–(\s-])",c)
    if not m: return None,c
    code=re.sub(r"\s*([?/;,])\s*",r"\1",m.group(1))
    rest=c[len(m.group(1)):].strip()
    return code,(c if rest else None)
def mapresp(code):
    return {"R":"resprouter","K":"obligate"}.get(code,code)
def parse_name(n):
    notes=[];native="native";raw=n
    if n.startswith("(*?)"): n=n[4:]; native=""; notes.append(f"name printed as '{raw}'")
    elif n.startswith("*"): n=n[1:]; native="exotic"
    n=hy(n)
    paren=re.search(r"\s*\(([^)]*)\)\s*$",n)
    if paren and paren.group(1) not in ("hybrid",):
        notes.append(f"name printed as '{hy(raw)}'"); n=n[:paren.start()].strip()
    elif "?(hybrid)" in n:
        notes.append(f"name printed as '{hy(raw)}'"); n=n.replace("?(hybrid)","hybrid")
    w=n.split()
    G=w[0]; rest=w[1:]
    subsp=""
    for i,t in enumerate(rest):
        if t in("subsp.","var.","f.","cv."):
            subsp=t+" "+" ".join(rest[i+1:]); rest=rest[:i]; break
    sp=" ".join(rest)
    if "?" in sp or "?" in subsp or "“" in sp:
        if not any("name printed" in x for x in notes): notes.append(f"name printed as '{hy(raw)}'")
        sp=sp.replace("?","").replace("“","").replace("”",""); subsp=subsp.replace("?","")
    return G,sp,subsp.strip(),native,notes
rows=[];src={};skipped=[]
XAN={"Xanthorrhoea arborea":(35,51),"Xanthorrhoea media":(17,39)}
for pdfpage,line,c in recs:
    fam,name,peak,lcr,nl,seedl,flr,fls,frr,frs,pjp,sjp=c[:12] if len(c)>=12 else (c+[""]*12)[:12]
    fam=c[0];name=c[1];peak=c[2];lcr=c[3];nl=c[4];seedl=c[5];flr=c[6];fls=c[7];frr=c[8];frs=c[9];pjp=c[10];sjp=c[11]
    G,Sp,subsp,native,nnotes=parse_name(name)
    jp=pdfpage+130
    base=dict(Genus=G,Species=Sp,subsp=subsp,native_status=native,Family=fam.capitalize(),Source=SRC,File_name=FN)
    notes0=[f"Appendix 1, p. {jp}"]+nnotes
    # site responses
    sites={}
    extra=[]
    for loc,cell in ((LCR,lcr),(NL,nl)):
        code,txt=sitecode(cell)
        if code:
            if code=="R" and txt and "(1)" in txt: sites[loc]="R(1)m.i.f"; extra.append(f"{loc} cell printed '{clean(txt)}'")
            else:
                sites[loc]=code
                if txt: extra.append(f"{loc} cell printed '{clean(txt)}'")
        elif txt: extra.append(f"{loc} cell printed '{clean(txt)}'")
    if seedl and not re.match(r"^\??\d",seedl): extra.append(f"seedlings column printed '{clean(seedl)}'")
    # times
    tv={}; tn=[]; sjp_unit=""
    def nonunder(raw): return raw and not raw.strip().startswith("<u>")
    def flow(raw,col,label):
        if not raw: return
        if not nonunder(raw) or not re.search(r"\d",raw):
            if raw.strip().startswith("<u>") : tn.append(f"first flowering (underlined: unclear whether from resprout or seed) printed '{clean(raw)}'")
            else: tn.append(f"{label} printed '{clean(raw)}'")
            return
        ex=exprs(raw)
        if not ex: tn.append(f"{label} printed '{clean(raw)}'"); return
        if re.search(r"buds",raw) and not re.search(r"\d\s*[wy]?\s*[,]",raw):
            tn.append(f"{label} printed '{clean(raw)}' (buds only; not entered)"); return
        e=ex[0]
        if not e["unit"]:
            tn.append(f"{label} printed '{clean(raw)}' (unit not stated for first value; not entered)"); return
        v,cv=val(e,True); tv[col]=v
        if cv: tn.append(f"{col} converted from {cv}")
        if raw!=f"{e['lo']}{e['unit']}" : tn.append(f"{label} printed '{clean(raw)}'")
        if "**" in raw: tn.append("bold value = sizable proportion of population flowering")
    flow(flr,"Time to first flower production resprout_repr3a","first flowering (resprout)")
    flow(fls,"Age at first flower production from seed_repr3","first flowering (seed)")
    def pj(raw,col,label,sj=False):
        nonlocal_unit=None
        if not raw: return None
        ex=exprs(raw)
        if not ex or not ex[0]["unit"]: tn.append(f"{label} printed '{clean(raw)}'"); return None
        e=ex[0]
        v,cv=val(e,not sj); tv[col]=v
        if cv: tn.append(f"{col} converted from {cv}")
        if not re.fullmatch(r"\d+(\.\d+)?[wy]",raw.strip()): tn.append(f"{label} printed '{clean(raw)}'")
        return {"w":"weeks","y":"years"}[e["unit"]]
    pj(pjp,"primary_juvenile_period","primary juvenile period")
    u=pj(sjp,"secondary_juvenile_period","secondary juvenile period",True)
    if u: sjp_unit=u
    # fruiting notes
    fr=[]
    if frr and frs and clean(frr)==clean(frs) and frr.strip().startswith("<u>"): fr.append(f"first fruiting (underlined: unclear whether from resprout or seed) '{clean(frr)}'")
    else:
        if frr: fr.append(f"first fruiting (resprout) '{clean(frr)}'")
        if frs: fr.append(f"first fruiting (seed) '{clean(frs)}'")
    tn+=fr
    # xanthorrhoea site split
    split={}
    if name in XAN:
        nlw,lcw=XAN[name]
        for loc,w in ((NL,nlw),(LCR,lcw)): split[loc]=toyears(w)
        tn=[x for x in tn if "Time to first flower production resprout_repr3a" not in x and "first flowering (resprout)" not in x]
        tv.pop("Time to first flower production resprout_repr3a",None)
        flnote=f"Time to first flower production resprout_repr3a per catchment from text p. 137 (Narrabeen Lagoon {nlw} weeks; Lane Cove River {lcw} weeks), converted from weeks; table prints '{clean(flr)}'"
    fire=dict(Fire_type="wildfire",Fire_season_categorical="Summer",Fire_severity_categorical="High")
    firenote="January 1994 wildfire (season derived from date); severity from text: fires generally of very high intensity"
    def mk(loc,resp,times,notes,coords=True,shared=False):
        r=dict(base); r.update(fire)
        r["Location_name"]=loc
        if coords: r["Latitude"]="-33.75"; r["Longitude"]="151.0833"
        if resp: r["fire_response categorical_surv1"]=mapresp(resp)
        r.update(times)
        if "secondary_juvenile_period" in times: r["Time_unit"]=sjp_unit
        r["Notes"]="; ".join([x for x in notes+[firenote] if x])
        rows.append(r); src[id(r)]=line
    if len(sites)==0:
        if tv:
            mk(BOTH,None,tv,notes0+tn+extra+["fire response not recorded for either catchment; site not stated, so shared row"],coords=False)
        else: skipped.append(name)
    elif len(sites)==1:
        loc=list(sites)[0]
        t=dict(tv)
        n=list(tn)
        if split:
            t["Time to first flower production resprout_repr3a"]=split[loc]; n.append(flnote)
        mk(loc,sites[loc],t,notes0+n+extra)
    else:
        for loc in (LCR,NL):
            t={}; n=[]
            if split: t["Time to first flower production resprout_repr3a"]=split[loc]; n.append(flnote)
            mk(loc,sites[loc],t,notes0+n+extra)
        if tv:
            mk(BOTH,None,tv,notes0+tn+["value printed once for both catchments, not split by catchment"],coords=False)
print("rows",len(rows),"species",len(recs),"skipped",len(skipped))
random.seed(int(sys.argv[1]) if len(sys.argv)>1 and sys.argv[1].isdigit() else 3)
for r in random.sample(rows,4):
    print(src[id(r)]); print({k:v for k,v in r.items() if k not in("Source","File_name","Fire_type","Fire_season_categorical","Fire_severity_categorical","Genus","Species")}); print()
if "--write" in sys.argv:
    append(rows); open("/tmp/kub_skipped.txt","w").write("\n".join(skipped))
E
