def mapresp(code):
    return {"R":"resprouter","K":"obligate"}.get(code,code)
def parse_name(n):
    notes=[];native="native";raw=n
    if n.startswith("(*?)"): n=n[4:]; native=""; notes.append(f"name printed as '{raw}'")
    elif n.startswith("*"): n=n[1:]; native="exotic"
    n=hy(n)
    paren=re.search(r"\s*\(([^)]*)\)\s*$",n)
    if paren and paren.group(1) not in ("hybrid",):
        notes.append(f"name printed as '{hy(raw)}'"); n=n[:paren.start()].strip()
    elif "?(hybrid)" in n:
        notes.append(f"name printed as '{hy(raw)}'"); n=n.replace("?(hybrid)","hybrid")
    w=n.split()
    G=w[0]; rest=w[1:]
    subsp=""
    for i,t in enumerate(rest):
        if t in("subsp.","var.","f.","cv."):
            subsp=t+" "+" ".join(rest[i+1:]); rest=rest[:i]; break
    sp=" ".join(rest)
    if "?" in sp or "?" in subsp or "“" in sp:
        if not any("name printed" in x for x in notes): notes.append(f"name printed as '{hy(raw)}'")
        sp=sp.replace("?","").replace("“","").replace("”",""); subsp=subsp.replace("?","")
