        if resp: r["fire_response categorical_surv1"]=mapresp(resp)
        r.update(times)
        if "secondary_juvenile_period" in times: r["Time_unit"]=sjp_unit
        r["Notes"]="; ".join([x for x in notes+[firenote] if x])
        rows.append(r); src[id(r)]=line
    if len(sites)==0:
        if tv:
            mk(BOTH,None,tv,notes0+tn+extra+["fire response not recorded for either catchment; site not stated, so shared row"],coords=False)
        else: skipped.append(name)
    elif len(sites)==1:
